/****** Object:  Stored Procedure dbo.RC_AtackBFB    Script Date: 28.11.2008 19:52:26 ******/

CREATE proc RC_AtackBFB
@serverid int,
@uid varchar(10),
@uchr varchar(10)
as

set nocount on
while 1=1
begin
declare @nhour int
	,@nmny int
	,@items varbinary(760)
set @nhour=cast(DATENAME ( Hour , getdate()) as int)
if @nhour<22 and @nhour>7 begin
	select '只有在 22:00 - 7:59 时间段内可以申请攻堡 !'
	break
end
if EXISTS (select GuildName from BFB_SBK where ServerID=@serverid and IDX=1) begin
	select '已经有盟申请攻堡了 !'
	break
end 
if EXISTS (select memb___id from MEMB_INFO where memb___id=@uid)
begin
	select @nmny=[Money],@items=Inventory from Character where AccountId=@uid and Name=@uchr
	if @nmny is null or @items is null begin
		select '角色没MU币或者装备栏为空 !'
		break
	end
	declare @gname varchar(50)
	select @gname=G_Name from Guild where g_Master=@uchr
	if @gname is null begin
		select '只有盟主才可以申请 !'
		break
	end
	if (select count(*) from GuildMember where G_Name=@gname)<10 begin
		select '成员必须有10人以上 !'
		break
	end
	if EXISTS (select GuildName from BFB_SBK where ServerID=@serverid and IDX=1 and GuildName=@gname) begin
		select '不能自己攻自己呀　！'
		break
	end
	if @nmny<50000000 begin
		select '手续费不足　！'
		break
	end
	declare @bh int
		,@lvl int
		,@itm binary(10)
		,@ec int
		,@ritems varbinary(760)
	set @itm=substring(@items,121,10)
	set @bh=(cast(substring(@Itm,8,1) as int) & 0x0080)*2+cast(substring(@itm,1,1) as int)
	set @lvl=(cast(substring(@Itm,2,1) as int) & 0x0078)/8
	if substring(@itm,1,1)=0xff or @bh<>0x1d3 or @lvl<>5 begin
		select '没找到攻堡必须的任务物品　！'
		break
	end
	set @ritems=substring(@items,1,120)+0xFFFFFFFFFFFFFFFFFFFF+substring(@items,131,630)

	begin tran
	update Character set [money]=[money]-50000000,Inventory=@ritems where  AccountId=@uid and Name=@uchr
	set @ec=@@error
	Insert into BFB_SBK (ServerID,IDX,GuildName,GuildTT)
		values (@serverid,1,@gname,@uchr)
	set @ec=@@error | @ec
	if @ec<>0 begin
		rollback tran
		select '在加入申请数据库时出错 !'
	end else begin
		commit tran
		select '恭喜,攻堡申请成功 !'
	end
	break
end
else
	select '你好象把用户名输错了呀　！'
break
end


GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/****** Object:  Stored Procedure dbo.RC_GetSms    Script Date: 28.11.2008 19:52:26 ******/

CREATE proc RC_GetSms
@Acc varchar(10),
@PageNo int,
@PageSize int, 
@IsRead tinyint
AS
declare @intBeginID int
declare @intEndID int
declare @intRootRecordCount int
declare @intPageCount int
declare @intRowCount int
set nocount on
if (@IsRead<100)
select @intRootRecordCount = count(1) from RC_Sms where isRead=@IsRead and AccountId=@Acc
else
select @intRootRecordCount = count(1) from RC_Sms where AccountId=@Acc
if (@intRootRecordCount = 0)
begin
select -1
return
end
if (@PageNo - 1) * @PageSize > @intRootRecordCount
begin
select -2
return
end
set @intRowCount = (@PageNo - 1) * @PageSize + 1
set rowcount @intRowCount
if (@IsRead<100)
select @intBeginID = SmsId from RC_Sms where isRead=@IsRead and AccountId=@Acc order by SmsId desc
else
select @intBeginID = SmsId from RC_Sms where AccountId=@Acc order by SmsId desc
set @intRowCount = @PageNo * @PageSize
set rowcount @intRowCount
if (@IsRead<100)
select @intEndID = SmsId from RC_Sms where isRead=@IsRead and AccountId=@Acc order by SmsId desc
else
select @intEndID = SmsId from RC_Sms where AccountId=@Acc order by SmsId desc
set rowcount 0
set nocount off 
if (@IsRead<100)
select SmsId,Name,AccountId,Addresser,Title,STR(YEAR(SendDate))+'-'+LTRIM(STR(MONTH(SendDate)))+'-'+LTRIM(STR(DAY(SendDate))) AS SendDate,isRead from RC_Sms where isRead=@IsRead and AccountId=@Acc AND (SmsId between @intEndID AND @intBeginID) order by SmsId desc
else
select SmsId,Name,AccountId,Addresser,Title,STR(YEAR(SendDate))+'-'+LTRIM(STR(MONTH(SendDate)))+'-'+LTRIM(STR(DAY(SendDate))) AS SendDate,isRead from RC_Sms where AccountId=@Acc AND (SmsId between @intEndID AND @intBeginID) order by SmsId desc
select @@rowcount


GO
SET ANSI_NULLS OFF
GO
SET QUOTED_IDENTIFIER OFF
GO

/****** Object:  Stored Procedure dbo.RC_GuildMember    Script Date: 28.11.2008 19:52:26 ******/

CREATE proc RC_GuildMember 
AS
declare @intMax int, @i int, @num int
declare @name nvarchar(20)
set nocount on
select top 1 @intMax=Number from Guild order by Number desc
if (@intMax<1) return
set @i=1
while @i<=@intMax
begin
select @name=G_Name from Guild where Number=@i
if (@name is not null)
begin
select @num=count(1) from GuildMember where G_Name=@name
update Guild set MemberCount=@num where G_Name=@name
end
set @i=@i+1
end 
set nocount off


GO
SET ANSI_NULLS OFF
GO
SET QUOTED_IDENTIFIER OFF
GO

