end
set @intRowCount = (@PageNo - 1) * @PageSize + 1
set rowcount @intRowCount
select @intBeginID = ID from RC_News order by ID desc
set @intRowCount = @PageNo * @PageSize
set rowcount @intRowCount
select @intEndID = ID from RC_News order by ID desc
set rowcount 0
set nocount off 
select * from RC_News where ID between @intEndID and @intBeginID order by -OnTop,ID desc
select @@rowcount


