    AS
    SET NOCOUNT ON
    print '*********************************'
    print ' 5檬埃 荤侩等 矫胶袍 磊盔樊涝聪促.'
    print '*********************************'
    SELECT spid, cpu, physical_io 
    INTO #Temp1 FROM master..sysprocesses
    WAITFOR DELAY '0:00:05'  
    SELECT P.spid, P.cpu-T.cpu AS 'cpu 荤侩樊(ms)', 
    P.physical_io-T.physical_io AS 'Disk R/W樊(Page)',
    P.nt_username ' NT 荤侩磊疙', P.program_name '览侩橇肺弊伐', 
    P.hostname, P.cmd
    FROM master..sysprocesses P, #Temp1 T
    WHERE P.spid=T.spid 
    AND P.cpu-T.cpu+P.physical_io-T.physical_io+P.memusage > 0
    DROP TABLE #Temp1
    Return


GO
