	@i_MailAdminGuid	INT

AS
SET NOCOUNT ON

	
	DECLARE @i_AdminMailCount INT
	
	SELECT @i_AdminMailCount = MemoCount FROM T_FriendMain WHERE GUID = @i_MailAdminGuid
	
	IF(@i_AdminMailCount > 0)
	BEGIN
		SELECT 
			MemoIndex, GUID, FriendName, wDate, Subject, bRead,Memo 
		FROM 
			T_FriendMail 
