			WHERE 
				GUID = @i_MailAdminGuid
		
			UPDATE
				T_FriendMain
			SET
				MemoTotal = 0
			WHERE
				GUID = @i_MailAdminGuid

		IF @@ERROR = 0 
		BEGIN
			COMMIT TRANSACTION
		END
		ELSE
		BEGIN
			ROLLBACK TRANSACTION
		END



	END			
	


