CREATE Procedure [dbo].[WZ_PeriodItemInsert]

	@UserGuid		int,
	@CharacterName	varchar(10),
	@ItemCode		int,
	@OptionType		tinyint,
	@EffectType1		tinyint,
	@EffectType2		tinyint,
