/****** Object:  Trigger dbo.MembStat_RecordOnlineHours    Script Date: 28.11.2008 19:41:25 ******/
CREATE TRIGGER [MembStat_RecordOnlineHours] ON dbo.MEMB_STAT
AFTER UPDATE
AS
declare @memb___id varchar(10)
declare @connectstat tinyint
SELECT @memb___id=memb___id,@connectstat=connectstat FROM INSERTED
IF (@connectstat = 0) 
BEGIN
UPDATE [dbo].[MEMB_STAT]
 SET OnlineHours = OnlineHours + datediff(hour, ConnectTM, getdate()) 
 WHERE memb___id = @memb___id
END



GO
ALTER TABLE [dbo].[MEMB_STAT] ENABLE TRIGGER [MembStat_RecordOnlineHours]
GO
